.card {
  margin-inline: 16px;        /* margin-left + margin-right 相当 */
  padding-block: 12px;        /* padding-top + padding-bottom 相当 */
  margin-inline-start: 24px;  /* LTR では左、RTL では右 */
  border-inline-end: 1px solid; /* 文末方向のボーダー */
}

.tip {
  position: absolute;
  inset-block-start: 0;   /* top: 0 相当 */
  inset-inline-end: 0;    /* right: 0 相当（LTR） */
  inline-size: 200px;     /* width */
  block-size: auto;       /* height */
}

html[dir='rtl'] .card {
  /* 論理プロパティを使っていれば追加 CSS 不要で反転する */
}

/* ❌ 混ぜると direction 反転時にズレやすい */
.card { margin-left: 16px; padding-inline: 12px; }

/* ✅ 揃える */
.card { margin-inline-start: 16px; padding-inline: 12px; }
